\label{a5} 
We call $\big\langle \mathbb{P}_i,\,\mathbb{Q}_j : i \le i(*),\ j < i(*)\big\rangle$ a 
$*_\mu^\varepsilon$-\emph{iteration} provided that:
\begin{enumerate}
    \item[(a)] It is a $(<\mu)$-support iteration ($\mu$ is a regular cardinal).
\smallskip\noindent
    \item[(b)] If $i_1 < i_2 \le i(*)$ and $\mathrm{cf}(i_1) \ne \mu$ then $\mathbb{P}_{i_2} / \mathbb{P}_{i_1}$ satisfies $*_\mu^\varepsilon$.
\end{enumerate}

asy; e.g. for (1A) we can use (6).

We induct on $n$; for $n+1$ and given 
$d_{n+1} : \bigcup \big\{ [{}^{\alpha}2]^{n+1} : \alpha < \mu \big\} \to \sigma$ 
and $\mkern 1.5mu\overline{\mkern-1.5mu<\mkern-1.5mu}\mkern 1.5mu^{n+1} = \langle {<_\alpha^{n+1}} : \alpha < \mu \rangle$, we apply $\Pr_\mathrm{ehtn}^\mathrm{fe}(\mu, n, {<\sigma})$. We get $T$. 

Let $f = \mathrm{clp}_T : T \to {}^{\mu>}2$ be as in \ref{b2}(5). 
Define $\mkern 1.5mu\overline{\mkern-1.5mu<\mkern-1.5mu}\mkern 1.5mu^* = \langle {<_\alpha^*} : \alpha < \mu \rangle$ and $d_n$ as follows:
\begin{enumerate}
    \item For $\alpha < \mu$ and $\eta_0,\eta_1 \in {}^{\alpha}2$, $\mathrm{clp}_T(\nu_\ell) = \eta_\ell$, ${\ell\kern-.27ex g}(\nu_\ell) = \beta$ \underline{then} 
    $$\eta_0 <_\alpha^{n} \eta_1 \Leftrightarrow \nu_0 <_\alpha^{n+1} \nu_1$$

    \item for $\alpha < \mu$ and $\eta_0 <_\alpha^{n} \ldots <_\alpha^{n} \eta_{n-1}$, $\mathrm{clp}_T(\nu_\ell) = \eta_\ell$, ${\ell\kern-.27ex g}(\nu_\ell) = \beta$ and for $k < n$, $\rho < 2$ we have $\nu_k {\char 94} \langle \ell \rangle \lhd \rho_{k,\ell} \in \mathrm{sp}(T_{n+1}) \cap {}^{\gamma}2$. {If} $\gamma$ is minimal then $d_n(\{ \eta_0, \ldots \eta_{n-1} \})$ codes the set of the following objects $\mathbf{t}$:
    \begin{itemize}
        \item For some $\gamma > \alpha$ there are 
        $\rho_{k,\ell} \in \mathrm{sp}(T_{n+1}) \cap {}^{\gamma}2$ such that $\nu_k {\char 94} \langle \ell \rangle \unlhd \rho_{k,\ell}$ for $k < n$, $\ell < 2$ and $\mathbf{t}$ codes all the information on the sequence $\langle \rho_{k,\ell} : k < n, \ell < 2 \rangle$ (i.e. the order $<_\gamma^{n+1}$ and instances of $\mathbf{d}_{n+1}$). \qedhere
    \end{itemize}
\end{enumerate}

\label{c11} 
For a sequence $a = \langle a_i,\,e_i^* : i < \alpha\rangle$ with 
$a_i \subseteq i$ and $e_i \in \{1,2\}$,
we call $b \subseteq \alpha$ \emph{closed} (or `$a$-{closed}') if
\begin{enumerate}
    \item[(i)]  $i\in b \Rightarrow a_i \subseteq b$
\smallskip\noindent
    \item[(ii)] If $i < \alpha,$ $e_i^*=1$, and $\sup(b \cap i) = i$ then $i \in b$.
\end{enumerate}

